--ptf-boundary-closest-note-image-9x2
Content-Type: text/javascript; charset=utf-8
Content-Disposition: attachment; filename="fluid.demos.ai.closestNoteImageGen"
Content-Description: layer

fluid.def("fluid.demos.ai.closestNoteImageGen", {
    $layers: ["fluid.demos.imageGenerator", "fluid.topLevelWidget"],
    // The closest-note finder is the supplier: it keeps computing against this shape's position, but shares
    // this widget's view, so none of its markup renders of its own. Its member name and layer nickname both
    // read closestNoteFinder, so its own {closestNoteFinder} references resolve exactly as they did free-standing
    closestNoteFinder: {
        $component: {
            $layers: "fluid.demos.closestNoteFinder",
            view: "{closestNoteImageGen}.view"
        }
    },
    // The image search prompt follows the text of the closest sticky note as the widget is moved
    state: {
        prompt: "{closestNoteFinder}.noteText"
    }
});
--ptf-boundary-closest-note-image-9x2
